from pathlib import Path
import argparse,json,time,hashlib
import numpy as np
from scipy.sparse import load_npz
from scipy.sparse.linalg import expm_multiply
w=Path(__file__).resolve().parent;p=argparse.ArgumentParser();p.add_argument('gauge',choices=['production','spatialnorm']);p.add_argument('--stop',type=float,default=2.);p.add_argument('--pilot-only',action='store_true');a=p.parse_args();g=a.gauge;meta=json.loads((w/f'{g}-cache0.0001-metadata.json').read_text());N=meta['points'];h=meta['spacing'];J=load_npz(w/f'{g}-projected-J20.npz');field=np.ones(20);field[[0,1,2,3,4,5,16,17,18,19]]=1/h;D=np.tile(field,N);K=J.multiply(D[:,None]).multiply((1/D)[None,:]).tocsr();K.sort_indices();trace=float(J.diagonal().sum());vs=dict(np.load(w.parent/f'{g}-validation-vectors.npz'));names=['gauge_pulse','shell_random'];B=np.column_stack([vs[n] for n in names]);norm=np.linalg.norm(B,axis=0);B/=norm[None,:];res={'gauge':g,'semantics':'exact constant block similarity K=T J20 T^-1; configuration {chi,g,alpha,beta} multiplied by1/h; momenta {P,A,Lambda,Theta} unchanged. Outputs multiplied byT^-1. J20 is projected continuous native global tangent, not native finite-RK3 map.','spacing':h,'configuration_scale':1/h,'norm1_unbalanced':float(abs(J).sum(axis=0).max()),'norm1_balanced':float(abs(K).sum(axis=0).max()),'matrix_shape':list(J.shape),'matrix_nnz':int(J.nnz),'balanced_matrix_nnz':int(K.nnz),'trace_relative_difference':float(abs(K.diagonal().sum()-trace)/abs(trace)),'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'pilot':{}}
print('similarity',g,res,flush=True);t0=time.monotonic();t=time.monotonic();Y=expm_multiply(K,D[:,None]*B,start=0,stop=.01,num=2,traceA=trace)[-1]/D[:,None];res['pilot']['balanced_seconds']=time.monotonic()-t;print('balanced pilot',g,res['pilot']['balanced_seconds'],np.linalg.norm(Y,axis=0).tolist(),flush=True);t=time.monotonic();plain=expm_multiply(J,B,start=0,stop=.01,num=2,traceA=trace)[-1];res['pilot']['unbalanced_seconds']=time.monotonic()-t;res['pilot']['balanced_vs_unbalanced_relative_state_l2']=(np.linalg.norm(Y-plain,axis=0)/np.linalg.norm(plain,axis=0)).tolist();res['pilot']['euclidean_amplification']=np.linalg.norm(Y,axis=0).tolist();native=np.load(w/f'{g}-rk3-t0.01.npz');res['pilot']['balanced_vs_native_final_only_relative_initial_l2']=np.linalg.norm(Y-native['native_final_only'],axis=0).tolist();res['pilot']['balanced_vs_native_half_relative_initial_l2']=np.linalg.norm(Y-native['native_final_only_half'],axis=0).tolist();res['pilot']['balanced_vs_projected_RK3_relative_initial_l2']=np.linalg.norm(Y-native['projected_every_RHS'],axis=0).tolist();np.savez_compressed(w/f'{g}-balanced-pilot-t0.01.npz',balanced=Y,unbalanced=plain,initial=B);(w/f'{g}-balanced-pilot-t0.01.json').write_text(json.dumps(res,indent=2)+'\n');print('pilot validated',g,res['pilot'],flush=True)
if a.pilot_only:raise SystemExit(0)
t=time.monotonic();times=np.linspace(0,a.stop,int(round(a.stop/.025))+1);values=expm_multiply(K,D[:,None]*B,start=0,stop=a.stop,num=len(times),traceA=trace);values/=D[None,:,None];res['seconds']=time.monotonic()-t;res['total_seconds']=time.monotonic()-t0;res['stop']=a.stop;res['samples']=len(times);res['final_euclidean_amplification']=np.linalg.norm(values[-1],axis=0).tolist();np.savez_compressed(w/f'{g}-balanced-expm-t{a.stop}.npz',times=times,values=values,names=np.asarray(names),initial_original_norms=norm);(w/f'{g}-balanced-expm-t{a.stop}.json').write_text(json.dumps(res,indent=2)+'\n');print('done balanced',g,res['seconds'],res['final_euclidean_amplification'],flush=True)
